export const CREATIVE_CATEGORIES=[
 ['lifestyle','Lifestyle photo','environment','A candid lifestyle photograph of a person enjoying a quiet morning in a sunlit café.','Natural window light','Environmental composition','35mm'],
 ['fashion','Fashion photo','wardrobe','A fashion editorial featuring a complete contemporary outfit, natural posture and authentic fabric.','Soft directional light','Full-body editorial','50mm'],
 ['product','Product photo','product','A premium perfume bottle photographed as a clean commercial packshot.','Controlled studio softbox','Centered product hero','85mm'],
 ['vector','Vector illustration','detail','A friendly botanical illustration with simple geometric shapes and a restrained palette.','Flat graphic shading','Balanced graphic composition','Orthographic'],
 ['3d','3D illustration','product','A playful sculptural mascot with rounded forms and tactile matte materials.','Soft studio light','Three-quarter view','Orthographic'],
 ['interior','Interior','background','A calm contemporary living room with warm wood, natural textiles and believable proportions.','Daylight through windows','Architectural wide view','24mm, straight verticals'],
 ['commercial','Commercial illustration','concept','A confident editorial illustration for a creative campaign, with one clear visual metaphor.','Coherent graphic shading','Hero with space for copy','Orthographic']
];
export const IMAGE_RECIPES=[['character','Hồ sơ nhân vật','person'],...CREATIVE_CATEGORIES.map(([id,label,icon])=>[id,label,icon]),['poster','Poster & key visual','grid'],['logo','Logo & nhận diện','prompt']];
export function recipeDefaults(id='lifestyle'){const category=CREATIVE_CATEGORIES.find(c=>c[0]===id)||CREATIVE_CATEGORIES[0];const extra={poster:['A clear campaign key visual with one focal point and deliberate space for typography.','Hero with space for copy','4:3'],logo:['An original minimal symbol with a distinctive silhouette and a clean single-color construction.','Centered symbol','1:1'],character:['One character reference image with consistent identity, front, side and back at matched scale.','Aligned character views','16:9']}[id];return{kind:'image',category:id,brief:extra?.[0]||category[3],setting:'',composition:extra?.[1]||category[5],lighting:id==='logo'?'Flat graphic shading':category[4],lens:id==='logo'?'Orthographic':category[6],palette:id==='logo'?'Single-color symbol':'Restrained, coherent colors',materials:'',text:'',negative:'',ratio:extra?.[2]||(id==='fashion'?'3:4':'4:3'),duration:5,camera:'Static camera',motion:'Subtle natural movement',beginning:'Establish the subject and setting',middle:'One clear action',ending:'Settle naturally',lockSubject:true}}
export function validateCreativePrompt(c,refs=[]){const issues=[];if(!c.brief?.trim())issues.push('Nhập ý tưởng chính trước.');if(c.brief?.length>12000)issues.push('Rút gọn ý tưởng còn dưới 12.000 ký tự.');if(refs.length>5)issues.push('Chọn tối đa 5 ảnh tham chiếu.');if(c.kind==='video'&&![3,5,7,8,10].includes(Number(c.duration)))issues.push('Chọn video dài 3, 5, 7, 8 hoặc 10 giây.');if(c.kind==='video'&&/static|locked|cố định/i.test(c.camera)&&/dolly|orbit|pan|zoom camera|camera move/i.test(c.motion))issues.push('Camera đang cố định nhưng chuyển động yêu cầu di chuyển máy. Đổi một trong hai.');if(c.kind==='video'&&!['16:9','9:16','1:1'].includes(c.ratio))issues.push('Video dùng khung 16:9, 9:16 hoặc 1:1.');return issues}
export function creativeManifest(c,refs=[]){const d=Number(c.duration)||5;return{version:1,kind:c.kind||'image',style:c.category,brief:c.brief.trim(),scene:{setting:c.setting?.trim()||undefined,composition:c.composition,lighting:c.lighting,palette:c.palette,lens:c.lens,materials:c.materials?.trim()||undefined},references:refs.map((r,i)=>({tag:r.tag,role:r.role||(i?'style and materials only':'primary subject'),preserve:c.lockSubject?'identity, geometry, materials, branding and proportions':'follow the brief'})),output:{ratio:c.ratio,count:1,...(c.kind==='video'?{durationSeconds:d,camera:c.camera,motion:c.motion,beats:[{from:0,to:Number((d*.25).toFixed(2)),action:c.beginning},{from:Number((d*.25).toFixed(2)),to:Number((d*.75).toFixed(2)),action:c.middle},{from:Number((d*.75).toFixed(2)),to:d,action:c.ending}]}:{format:'single raster image'})},exactText:c.text?.trim()||null,avoid:c.negative?.trim()||null,lockSubject:!!c.lockSubject}}
export function compileCreativePrompt(c,refs=[]){const m=creativeManifest(c,refs),style=CREATIVE_CATEGORIES.find(x=>x[0]===c.category)?.[1]||IMAGE_RECIPES.find(x=>x[0]===c.category)?.[1]||c.category;const lines=[`CREATIVE BRIEF — ${c.kind==='video'?'VIDEO':'IMAGE'}`,`Visual direction: ${style}.`,'SUBJECT AND INTENT:\n'+m.brief];for(const[k,v]of Object.entries(m.scene))if(v)lines.push(k.toUpperCase()+': '+v+'.');if(m.references.length)lines.push('REFERENCE ROLES:\n'+m.references.map((r,i)=>`${i+1}. @${r.tag}: ${r.role}. Preserve ${r.preserve}.`).join('\n'));if(c.lockSubject&&refs.length)lines.push('Keep the primary subject recognizable. Transfer style only from supporting references. Do not blend identities or replace product geometry.');if(c.kind==='video')lines.push(`DURATION: ${m.output.durationSeconds} seconds. CAMERA: ${c.camera}. MOTION: ${c.motion}.`,'TIMELINE:\n'+m.output.beats.map(b=>`${b.from}–${b.to}s: ${b.action}.`).join('\n'),'Maintain temporal continuity, consistent lighting and physically plausible movement. No unrequested cuts, dialogue, lip movement or soundtrack.');if(c.category==='vector'||c.category==='logo')lines.push('Use clean flat shapes, crisp contours and intentional negative space. This is a raster visualization of vector-style artwork, not an editable SVG.');if(c.category==='interior')lines.push('Keep straight architectural verticals, consistent scale, functional circulation and coherent perspective.');if(c.category==='product')lines.push('Keep packaging, label, cap, material and proportions exact when supplied. Match realistic reflections and contact shadows.');lines.push(c.text?.trim()?'EXACT TEXT: '+c.text.trim()+'. Preserve spelling; add no other words.':c.category==='logo'?'No lettering, captions or watermarks. Render only the requested original symbol.':'No added text, captions, logos or watermarks.',c.negative?.trim()?'AVOID: '+c.negative.trim()+'.':'Avoid distorted anatomy, duplicated objects, broken geometry and artificial oversharpening.',`OUTPUT: One finished ${c.kind==='video'?'video clip':'image'}, aspect ratio ${c.ratio}. No before/after or contact sheet unless the brief explicitly asks for one.`);return lines.join('\n\n')}
export function originalBrief(prompt=''){const marker='[USER BRIEF]';if(prompt.includes(marker))return prompt.split(marker).slice(1).join(marker).trim();const match=prompt.match(/SUBJECT AND INTENT:\n([\s\S]*?)(?=\n\n[A-Z][A-Z ]*:|$)/);return match?match[1].trim():prompt.trim()}
